#include <stdio.h>
int main() {
    char s[1005]; if (scanf("%s", s) != 1) return 0;
    long long so = 0, se = 0, po = 1, pe = 1;
    int has_o = 0, has_e = 0;
    for (int i = 0; s[i]; i++) {
        int d = s[i] - '0';
        if (d % 2 != 0) { so += d; po *= d; has_o = 1; }
        else { se += d; pe *= d; has_e = 1; }
    }
    if (!has_o) po = 0;
    if (!has_e) pe = 0;
    printf("Sum of Odd:%lld\nSum of Even:%lld\nProduct of ODD:%lld\nProduct of Even:%lld\n", so, se, po, pe);
    return 0;
}

