                else { se += d; pe *= d; hasE = true; }
            }
            if (!hasO) po = 0;
            if (!hasE) pe = 0;
            System.out.println("Sum of Odd:" + so);
            System.out.println("Sum of Even:" + se);
            System.out.println("Product of ODD:" + po);
            System.out.println("Product of Even:" + pe);
        }
    }
}

